import { v4 as uuidv4 } from 'uuid';
import VoiceResponse from 'twilio/lib/twiml/VoiceResponse';
import { saveCallData } from '../../../lib/storage';

export default function handler(req, res) {
  const twiml = new VoiceResponse();
  const callSid = req.body.CallSid || `mock-${uuidv4()}`;
  const caller = req.body.From || 'Unknown';

  // Initialize call data
  saveCallData(callSid, {
    from: caller,
    status: 'screening',
    startTime: new Date().toISOString(),
  });

  // Greet and ask for purpose
  const gather = twiml.gather({
    input: 'speech',
    action: '/api/voice/screen',
    timeout: 3,
    speechTimeout: 'auto',
  });

  gather.say({ voice: 'alice' }, 
    "Hello, you have reached Remy's AI assistant. Remy is currently busy. Please state your name and the reason for your call, and I will see if I can put you through."
  );

  // If no input, loop or voicemail (simplified to voicemail here)
  twiml.say({ voice: 'alice' }, "I didn't hear anything. Please leave a message after the beep.");
  twiml.record({
    action: '/api/voice/recording',
    transcribe: true,
    transcribeCallback: '/api/voice/recording'
  });

  res.setHeader('Content-Type', 'text/xml');
  res.status(200).send(twiml.toString());
}
